import sys

data = sys.stdin.read().split()
a0 = int(data[0])
b0 = int(data[1])
from math import isqrt
def dsum(v):
    s = 0
    while v:
        s += v % 10
        v //= 10
    return s
def dmax(v):
    m = 0
    while v:
        if v % 10 > m:
            m = v % 10
        v //= 10
    return m
def hasdig(v, d):
    while v:
        if v % 10 == d:
            return True
        v //= 10
    return False
def nothas(v, d):
    return not hasdig(v, d)
def uniqdig(v):
    seen = set()
    while v:
        d = v % 10
        if d in seen:
            return False
        seen.add(d)
        v //= 10
    return True
def ispal(v):
    t = v
    r = 0
    while t:
        r = r * 10 + t % 10
        t //= 10
    return r == v
def issq(v):
    r = isqrt(v)
    return r * r == v
def isp(v):
    if v < 2:
        return False
    d = 2
    while d * d <= v:
        if v % d == 0:
            return False
        d += 1
    return True
def deven(v):
    while v:
        if v % 2 == 0:
            return True
        v //= 10
    return False
def popodd(v):
    return bin(v).count("1") % 2 == 1
def cntdig(v, d):
    c = 0
    while v:
        if v % 10 == d:
            c += 1
        v //= 10
    return c
c = 0
for x in range(a0, b0 + 1):
    if hasdig(x, 7):
        c += 1
print(c)

